INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Accueil', '<shortcode>[simple-slider key=\"home-slider\"][/simple-slider]</shortcode><shortcode>[featured-product-categories title=\"Top Categories\" subtitle=\"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Phasellus blandit massa enim Nullam nunc varius.\"][/featured-product-categories]</shortcode><shortcode>[product-collections title=\"A change of Season\" subtitle=\"Update your wardrobe with new seasonal trend\"][/product-collections]</shortcode><shortcode>[flash-sale title=\"Deal of the day\" subtitle=\"Best Deals For You\" show_popup=\"yes\"][/flash-sale]</shortcode><shortcode>[featured-products title=\"Our Picks For You\" subtitle=\"Always find the best ways for you\" limit=\"8\"][/featured-products]</shortcode><shortcode>[trending-products title=\"Trending Products\" subtitle=\"Products on trending\" limit=\"5\"][/trending-products]</shortcode><shortcode>[news title=\"Visit Our Blog\" subtitle=\"Our Blog updated the newest trend of the world regularly\"][/news]</shortcode><shortcode>[theme-galleries title=\"@ OUR GALLERIES\" subtitle=\"Our latest fashion galleries images\" limit=\"8\"][/theme-galleries]</shortcode><shortcode>[site-features icon1=\"icon-truck\" title1=\"FREE SHIPPING\" subtitle1=\"Free shipping on all US order or order above $200\" icon2=\"icon-life-buoy\" title2=\"SUPPORT 24/7\" subtitle2=\"Contact us 24 hours a day, 7 days a week\" icon3=\"icon-refresh-ccw\" title3=\"30 DAYS RETURN\" subtitle3=\"Simply return it within 30 days for an exchange\" icon4=\"icon-shield\" title4=\"100% PAYMENT SECURE\" subtitle4=\"We ensure secure payment with PEV\"][/site-features]</shortcode>', 1, NULL, 'homepage', 'Page d\'accueil', 'published', '2024-01-29 02:42:47', '2024-02-25 17:04:23'),
(2, 'Blog', '<p style=\"text-align: center\">We always share fashion tips with the hope you guys will find the best style for yourself.<br />Besides, we update the fashion trend as soon as we can.<br />Enjoy your journey!</p>', 1, NULL, 'default', NULL, 'published', '2024-01-29 02:42:47', '2024-01-29 02:42:47'),
(3, 'Contact', '<p>[contact-form][/contact-form]</p>', 1, NULL, 'default', NULL, 'published', '2024-01-29 02:42:47', '2024-01-29 02:42:47'),
(4, 'Politique des Cookies', '<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>', 1, NULL, 'default', '', 'published', '2024-01-29 02:42:47', '2024-02-22 03:40:45'),
(5, 'FAQs', '<div>[faqs][/faqs]</div>', 1, NULL, 'default', NULL, 'published', '2024-01-29 02:42:47', '2024-01-29 02:42:47'),
(8, 'Politique de confidentialité', '<p>Notre politique de confidentialité</p>', 1, NULL, 'default', 'Notre politique de confidentialité', 'published', '2024-04-06 09:29:40', '2024-04-06 09:29:40'),
(9, 'Conditions générales', '<p>Nos conditions générales</p>', 1, NULL, 'default', 'Nos conditions générales', 'published', '2024-04-06 09:30:27', '2024-04-06 09:30:27');
